const lookbackDays = $input.first().json.LOOKBACK_DAYS || 7;
const sinceDate = new Date(Date.now() - lookbackDays * 24 * 60 * 60 * 1000).toISOString();

return [{
  json: {
    ...$input.first().json,
    sinceDate: sinceDate,
    formattedSince: sinceDate.split('T')[0]
  }
}];

const config = $('Calculate Date Window').item.json;
const commitsData = $('Fetch Weekly Commits').all().map(i => i.json);
const issuesData = $('Fetch Closed Issues').all().map(i => i.json);
const prsData = $('Fetch Merged PRs').all().map(i => i.json);

// Filter merged PRs within the last 7 days
const sinceEpoch = new Date(config.sinceDate).getTime();
const mergedPRs = prsData.filter(pr => pr.merged_at && new Date(pr.merged_at).getTime() >= sinceEpoch);

// Filter issues (GitHub /issues returns PRs as well, exclude them)
const pureIssues = issuesData.filter(issue => !issue.pull_request);

// Extract readable items
const commitList = (Array.isArray(commitsData) ? commitsData : []).slice(0, 40).map(c => `- ${c.commit?.message?.split('\n')[0]} (@${c.author?.login || c.commit?.author?.name || 'unknown'})`).join('\n');
const prList = mergedPRs.map(pr => `- #${pr.number} ${pr.title} by @${pr.user?.login}`).join('\n') || 'None this week';
const issueList = pureIssues.map(i => `- #${i.number} ${i.title}`).join('\n') || 'None this week';

const language = (config.SUMMARY_LANGUAGE || 'EN').toUpperCase();
const langInstruction = language === 'FR' 
  ? 'Write the narrative report in French.' 
  : 'Write the narrative report in English.';

const prompt = `You are an elite Engineering Executive Assistant.
Generate an engaging, narrative executive dev summary for the GitHub repository: ${config.GITHUB_OWNER}/${config.GITHUB_REPO}.
Period: Last ${config.LOOKBACK_DAYS} days (since ${config.formattedSince}).
Language: ${langInstruction}

Metrics:
- Total Commits: ${commitsData.length || 0}
- Merged Pull Requests: ${mergedPRs.length}
- Closed Issues: ${pureIssues.length}

Details:
### Merged Pull Requests:
${prList}

### Closed Issues:
${issueList}

### Recent Commit Highlights:
${commitList || 'No commit activity'}

Structure the summary as follows:
1. 🌟 **Executive Overview**: High-level narrative of what the team accomplished.
2. 🚀 **Key Shipments & Features**: Highlights of merged PRs and core updates.
3. 🐛 **Resolved Issues & Quality Improvements**: Bugs crushed and operational gains.
4. 📊 **Weekly Activity Metrics**: Quick table or bullet stats.
5. 🎯 **Next Week Focus**: Recommended focus areas based on recent momentum.

Keep the tone professional, inspiring, and concise (under 400 words).`;

return [{
  json: {
    ...config,
    prompt: prompt,
    summaryLanguage: language,
    totalCommits: commitsData.length || 0,
    mergedPRCount: mergedPRs.length,
    closedIssueCount: pureIssues.length
  }
}];

const claudeResponse = $input.first().json;
const promptConfig = $('Aggregate Activity & Build Prompt').item.json;

const narrativeText = claudeResponse.content?.[0]?.text || 'No response generated from Claude.';
const header = `📢 **Weekly Dev Summary — ${promptConfig.GITHUB_OWNER}/${promptConfig.GITHUB_REPO}**\n*Period: ${promptConfig.formattedSince} to Present | Generated by Claude Sonnet*\n\n`;

const formattedMessage = header + narrativeText;

return [{
  json: {
    destinationWebhookUrl: promptConfig.DESTINATION_WEBHOOK_URL,
    discordPayload: {
      content: formattedMessage.slice(0, 1950) // Discord 2000-character safety limit
    },
    slackPayload: {
      text: formattedMessage
    },
    emailPayload: {
      subject: `Weekly Dev Summary: ${promptConfig.GITHUB_OWNER}/${promptConfig.GITHUB_REPO}`,
      body: formattedMessage
    },
    fullSummaryText: formattedMessage
  }
}];
